        "kind": "text",
        "text": "#!/usr/bin/env bash\r\n# Usage: bash gitcode-login-wait.sh --session-id <id>\r\n# Polls until login completes or timeout (300s).\r\nset -euo pipefail\r\n\r\nSERVER_URL=\"http://127.0.0.1:7654\"\r\nSESSION_ID=\"\"\r\nTIMEOUT=300\r\n\r\nwhile [ $# -gt 0 ]; do\r\n  case \"$1\" in\r\n    --server-url) SERVER_URL=\"$2\"; shift 2 ;;\r\n    --session-id) SESSION_ID=\"$2\"; shift 2 ;;\r\n    --timeout) TIMEOUT=\"$2\"; shift 2 ;;\r\n    *) echo \"unknown: $1\" >&2; exit 1 ;;\r\n  esac\r\ndone\r\n\r\nif [ -z \"$SESSION_ID\" ]; then\r\n  echo \"Missing --session-id\" >&2\r\n  exit 1\r\nfi\r\n\r\nEND=$(( $(date +%s) + TIMEOUT ))\r\nwhile [ $(date +%s) -lt $END ]; do\r\n  result=$(curl -s \"$SERVER_URL/login/poll?session_id=$SESSION_ID\")\r\n  status=$(echo \"$result\" | grep -o '\"status\"[[:space:]]*:[[:space:]]*\"[^\"]*\"' | cut -d'\"' -f4)\r\n  if [ \"$status\" = \"authorized\" ]; then\r\n    echo \"SCAN_SUCCESS\"\r\n    exit 0\r\n  fi\r\n  sleep 2\r\ndone\r\n\r\necho \"TIMEOUT\"\r\nexit 1\r\n"
