        "text": "{\r\n  \"name\": \"local-life-admin\",\r\n  \"version\": \"0.1.0\",\r\n  \"private\": true,\r\n  \"type\": \"module\",\r\n  \"scripts\": {\r\n    \"dev\": \"vite\",\r\n    \"build\": \"vue-tsc && vite build\",\r\n    \"preview\": \"vite preview\",\r\n    \"lint\": \"eslint . --ext .vue,.ts,.tsx --fix\",\r\n    \"format\": \"prettier --write src/\"\r\n  },\r\n  \"dependencies\": {\r\n    \"vue\": \"^3.4.21\",\r\n    \"vue-router\": \"^4.3.0\",\r\n    \"pinia\": \"^2.1.7\",\r\n    \"element-plus\": \"^2.6.1\",\r\n    \"@element-plus/icons-vue\": \"^2.3.1\",\r\n    \"axios\": \"^1.6.7\",\r\n    \"echarts\": \"^5.5.0\",\r\n    \"vue-echarts\": \"^6.6.8\",\r\n    \"dayjs\": \"^1.11.10\",\r\n    \"nprogress\": \"^0.2.0\"\r\n  },\r\n  \"devDependencies\": {\r\n    \"@vitejs/plugin-vue\": \"^5.0.4\",\r\n    \"typescript\": \"^5.4.0\",\r\n    \"vite\": \"^5.1.4\",\r\n    \"vue-tsc\": \"^2.0.6\",\r\n    \"eslint\": \"^8.57.0\",\r\n    \"eslint-plugin-vue\": \"^9.22.0\",\r\n    \"@typescript-eslint/eslint-plugin\": \"^7.1.1\",\r\n    \"@typescript-eslint/parser\": \"^7.1.1\",\r\n    \"prettier\": \"^3.2.5\",\r\n    \"unplugin-auto-import\": \"^0.17.5\",\r\n    \"unplugin-vue-components\": \"^0.26.0\",\r\n    \"sass\": \"^1.71.1\"\r\n  }\r\n}"
