        "kind": "text",
        "text": "import axios, { AxiosInstance, AxiosRequestConfig, AxiosResponse } from 'axios'\r\nimport { ElMessage } from 'element-plus'\r\nimport { useUserStore } from '@/store/user'\r\nimport router from '@/router'\r\n\r\nconst service: AxiosInstance = axios.create({\r\n  baseURL: import.meta.env.VITE_API_PREFIX,\r\n  timeout: 15000,\r\n})\r\n\r\nservice.interceptors.request.use((config) => {\r\n  const userStore = useUserStore()\r\n  if (userStore.token) {\r\n    config.headers.Authorization = `Bearer ${userStore.token}`\r\n  }\r\n  return config\r\n})\r\n\r\nservice.interceptors.response.use(\r\n  (response: AxiosResponse) => {\r\n    const body = response.data\r\n    if (body?.code === 0) return body.data\r\n    ElMessage.error(body?.message || '请求失败')\r\n    return Promise.reject(body)\r\n  },\r\n  (error) => {\r\n    if (error.response?.status === 401) {\r\n      const userStore = useUserStore()\r\n      userStore.logout()\r\n      router.push('/login')\r\n    } else {\r\n      const msg = error.response?.data?.message\r\n        || (error.response?.data?.detail?.[0]?.msg && `参数错误：${error.response.data.detail[0].msg}`)\r\n        || error.message\r\n        || '网络异常'\r\n      ElMessage.error(msg)\r\n    }\r\n    return Promise.reject(error)\r\n  },\r\n)\r\n\r\nexport const request = <T = unknown>(config: AxiosRequestConfig): Promise<T> =>\r\n  service(config) as unknown as Promise<T>"
