        "path": "demo1/server/app/core/config.py",
        "size": 4111,
        "kind": "text",
        "text": "\"\"\"统一配置加载模块 - 基于 Pydantic Settings，支持环境变量与 .env 文件注入。\"\"\"\r\n\r\nfrom functools import lru_cache\r\nfrom typing import Optional\r\n\r\nfrom pydantic import Field\r\nfrom pydantic_settings import BaseSettings, SettingsConfigDict\r\n\r\n\r\nclass Settings(BaseSettings):\r\n    model_config = SettingsConfigDict(\r\n        env_file=\".env\",\r\n        env_file_encoding=\"utf-8\",\r\n        case_sensitive=False,\r\n        extra=\"ignore\",\r\n    )\r\n\r\n    # ===== 应用 =====\r\n    app_env: str = \"dev\"\r\n    app_debug: bool = True\r\n    app_name: str = \"local-life-server\"\r\n    app_host: str = \"0.0.0.0\"\r\n    app_port: int = 8000\r\n    app_timezone: str = \"Asia/Shanghai\"\r\n\r\n    # ===== JWT =====\r\n    jwt_secret_key: str = Field(default=\"change-me\", min_length=8)\r\n    jwt_algorithm: str = \"HS256\"\r\n    jwt_user_token_expire_days: int = 7\r\n    jwt_admin_token_expire_hours: int = 2\r\n\r\n    # ===== MySQL =====\r\n    mysql_host: str = \"127.0.0.1\"\r\n    mysql_port: int = 3306\r\n    mysql_user: str = \"root\"\r\n    mysql_password: str = \"root123\"\r\n    mysql_database: str = \"local_life\"\r\n    mysql_pool_size: int = 10\r\n    mysql_max_overflow: int = 20\r\n\r\n    # ===== Redis =====\r\n    redis_host: str = \"127.0.0.1\"\r\n    redis_port: int = 6379\r\n    redis_password: str = \"\"\r\n    redis_db: int = 0\r\n\r\n    # ===== MongoDB =====\r\n    mongo_host: str = \"127.0.0.1\"\r\n    mongo_port: int = 27017\r\n    mongo_user: str = \"\"\r\n    mongo_password: str = \"\"\r\n    mongo_database: str = \"local_life\"\r\n\r\n    # ===== Elasticsearch =====\r\n    es_host: str = \"127.0.0.1\"\r\n    es_port: int = 9200\r\n    es_user: str = \"\"\r\n    es_password: str = \"\"\r\n\r\n    # ===== MinIO =====\r\n    minio_endpoint: str = \"127.0.0.1:9000\"\r\n    minio_access_key: str = \"minioadmin\"\r\n    minio_secret_key: str = \"minioadmin\"\r\n    minio_bucket: str = \"local-life\"\r\n    minio_secure: bool = False\r\n\r\n    # ===== RabbitMQ =====\r\n    rabbitmq_host: str = \"127.0.0.1\"\r\n    rabbitmq_port: int = 5672\r\n    rabbitmq_user: str = \"guest\"\r\n    rabbitmq_password: str = \"guest\"\r\n\r\n    # ===== 第三方服务 =====\r\n    amap_api_key: str = \"\"\r\n    qweather_api_key: str = \"\"\r\n    ai_api_base: str = \"https://api.openai.com/v1\"\r\n    ai_api_key: str = \"\"\r\n    ai_model: str = \"gpt-3.5-turbo\"\r\n    jpush_app_key: str = \"\"\r\n    jpush_master_secret: str = \"\"\r\n    aliyun_censor_access_key: str = \"\"\r\n    aliyun_censor_access_secret: str = \"\"\r\n\r\n    # ===== 限流 =====\r\n    rate_limit_global: str = \"100/minute\"\r\n    rate_limit_login: str = \"5/minute\"\r\n\r\n    # ===== 中间件开关（本地开发可关闭非必须中间件） =====\r\n    use_sqlite: bool = True\r\n    redis_enabled: bool = False\r\n    mongo_enabled: bool = False\r\n    es_enabled: bool = False\r\n    minio_enabled: bool = False\r\n    celery_enabled: bool = False\r\n\r\n    # ===== 派生属性 =====\r\n    @property\r\n    def mysql_dsn(self) -> str:\r\n        if self.use_sqlite:\r\n            return \"sqlite+aiosqlite:///./local_life.db\"\r\n        return (\r\n            f\"mysql+aiomysql://{self.mysql_user}:{self.mysql_password}\"\r\n            f\"@{self.mysql_host}:{self.mysql_port}/{self.mysql_database}?charset=utf8mb4\"\r\n        )\r\n\r\n    @property\r\n    def redis_url(self) -> str:\r\n        pwd = f\":{self.redis_password}@\" if self.redis_password else \"\"\r\n        return f\"redis://{pwd}{self.redis_host}:{self.redis_port}/{self.redis_db}\"\r\n\r\n    @property\r\n    def mongo_url(self) -> str:\r\n        auth = \"\"\r\n        if self.mongo_user and self.mongo_password:\r\n            auth = f\"{self.mongo_user}:{self.mongo_password}@\"\r\n        return f\"mongodb://{auth}{self.mongo_host}:{self.mongo_port}\"\r\n\r\n    @property\r\n    def es_url(self) -> str:\r\n        return f\"http://{self.es_host}:{self.es_port}\"\r\n\r\n    @property\r\n    def rabbitmq_url(self) -> str:\r\n        return (\r\n            f\"amqp://{self.rabbitmq_user}:{self.rabbitmq_password}\"\r\n            f\"@{self.rabbitmq_host}:{self.rabbitmq_port}//\"\r\n        )\r\n\r\n    @property\r\n    def is_prod(self) -> bool:\r\n        return self.app_env == \"prod\"\r\n\r\n\r\n@lru_cache(maxsize=1)\r\ndef get_settings() -> Settings:\r\n    return Settings()\r\n\r\n\r\nsettings = get_settings()"
