        "path": "demo1/server/app/schemas/community.py",
        "size": 1443,
        "kind": "text",
        "text": "\"\"\"社区文化 Pydantic 模型。\"\"\"\r\n\r\nfrom datetime import datetime\r\n\r\nfrom pydantic import BaseModel, Field\r\n\r\n\r\nclass PostCreate(BaseModel):\r\n    section_id: str\r\n    title: str = Field(..., min_length=1, max_length=50)\r\n    content: str = Field(..., min_length=1, max_length=2000)\r\n    image_urls: list[str] = Field(default_factory=list, max_length=9)\r\n\r\n\r\nclass PostList(BaseModel):\r\n    post_id: str\r\n    author_id: str\r\n    author_name: str = \"\"\r\n    title: str\r\n    content: str\r\n    image_urls: list[str] = []\r\n    like_count: int = 0\r\n    comment_count: int = 0\r\n    liked: bool = False\r\n    created_at: datetime\r\n\r\n\r\nclass PostDetail(PostList):\r\n    section_id: str\r\n    status: str\r\n\r\n\r\nclass CommentCreate(BaseModel):\r\n    content: str = Field(..., min_length=1, max_length=500)\r\n    parent_id: str | None = Field(default=None, description=\"父评论ID，空=一级评论\")\r\n    reply_to_name: str | None = Field(default=None, description=\"被回复者昵称，仅二级回复有值\")\r\n\r\n\r\nclass CommentOut(BaseModel):\r\n    comment_id: str\r\n    post_id: str\r\n    author_id: str\r\n    author_name: str = \"\"\r\n    content: str\r\n    parent_id: str | None = None\r\n    replies: list[\"CommentOut\"] = []\r\n    created_at: datetime\r\n\r\n\r\nclass MessageSend(BaseModel):\r\n    session_id: str\r\n    content: str = Field(..., min_length=1, max_length=2000)\r\n    msg_type: str = \"text\"\r\n\r\n\r\nclass SessionCreate(BaseModel):\r\n    target_user_id: str"
