        "path": "demo1/server/app/schemas/trade.py",
        "size": 1485,
        "kind": "text",
        "text": "\"\"\"闲置交易 Pydantic 模型与订单状态枚举。\"\"\"\r\n\r\nfrom datetime import datetime\r\nfrom enum import Enum\r\n\r\nfrom pydantic import BaseModel, Field\r\n\r\n\r\nclass OrderStatus(str, Enum):\r\n    PENDING_PAY = \"pending_pay\"\r\n    PAID = \"paid\"\r\n    SHIPPED = \"shipped\"\r\n    COMPLETED = \"completed\"\r\n    CANCELED = \"canceled\"\r\n    REFUNDING = \"refunding\"\r\n    REFUNDED = \"refunded\"\r\n\r\n\r\nclass ProductCreate(BaseModel):\r\n    title: str = Field(..., min_length=1, max_length=50)\r\n    description: str | None = Field(None, max_length=1000)\r\n    price: float = Field(..., gt=0, le=999999.99)\r\n    category_id: str | None = None\r\n    image_urls: list[str] = Field(default_factory=list, min_length=1, max_length=6)\r\n    contact: str = Field(..., min_length=1, max_length=128)\r\n    stock: int = Field(1, ge=1, le=999999)\r\n\r\n\r\nclass ProductOut(BaseModel):\r\n    product_id: str\r\n    seller_id: str\r\n    title: str\r\n    description: str | None = None\r\n    price: float\r\n    image_urls: list[str] = []\r\n    contact: str | None = None\r\n    status: str\r\n    stock: int = 0\r\n    locked_count: int = 0\r\n    total_stock: int = 0\r\n    created_at: datetime\r\n\r\n\r\nclass OrderCreate(BaseModel):\r\n    product_id: str\r\n\r\n\r\nclass OrderOut(BaseModel):\r\n    order_id: str\r\n    buyer_id: str\r\n    seller_id: str\r\n    product_id: str\r\n    amount: float\r\n    status: str\r\n    created_at: datetime\r\n\r\n\r\nclass PayRequest(BaseModel):\r\n    channel: str = Field(\"wechat\", pattern=\"^(wechat|alipay|apple_pay|google_pay)$\")"
