        "path": "demo1/server/app/schemas/user.py",
        "size": 1751,
        "kind": "text",
        "text": "\"\"\"用户相关 Pydantic 请求/响应模型。\"\"\"\r\n\r\nfrom datetime import datetime\r\n\r\nfrom pydantic import BaseModel, EmailStr, Field, field_validator\r\n\r\n\r\n# ===== 请求 =====\r\nclass SendCodeRequest(BaseModel):\r\n    account: str = Field(..., description=\"手机号或邮箱\")\r\n\r\n\r\nclass RegisterRequest(BaseModel):\r\n    account: str = Field(..., min_length=5, max_length=64)\r\n    password: str = Field(..., min_length=8, max_length=20)\r\n    nickname: str = Field(..., min_length=2, max_length=32)\r\n\r\n\r\n    @field_validator(\"password\")\r\n    @classmethod\r\n    def validate_password(cls, v: str) -> str:\r\n        if not any(c.isalpha() for c in v) or not any(c.isdigit() for c in v):\r\n            raise ValueError(\"密码需同时包含字母与数字\")\r\n        return v\r\n\r\n\r\nclass LoginRequest(BaseModel):\r\n    account: str = Field(..., min_length=5, max_length=64)\r\n    password: str = Field(..., min_length=1)\r\n\r\n\r\nclass RefreshRequest(BaseModel):\r\n    refresh_token: str\r\n\r\n\r\nclass UserUpdate(BaseModel):\r\n    nickname: str | None = Field(None, min_length=2, max_length=32)\r\n    avatar_url: str | None = Field(None, max_length=512)\r\n    bio: str | None = Field(None, max_length=500)\r\n\r\n\r\n# ===== 响应 =====\r\nclass UserProfile(BaseModel):\r\n    user_id: str\r\n    account: str\r\n    nickname: str\r\n    avatar_url: str | None = None\r\n    bio: str | None = None\r\n    status: str\r\n    register_time: str | None = None\r\n\r\n\r\nclass LoginResponse(BaseModel):\r\n    access_token: str\r\n    refresh_token: str\r\n    user: UserProfile\r\n\r\n\r\nclass PublicProfile(BaseModel):\r\n    \"\"\"他人主页公开信息。\"\"\"\r\n\r\n    user_id: str\r\n    nickname: str\r\n    avatar_url: str | None = None\r\n    bio: str | None = None\r\n    post_count: int = 0\r\n    like_count: int = 0"
